import json,numpy as np
x=np.load('x2.npy'); names=['XL','mp','TPf','kpq','kiq','TQf','kvs']
p={k:float(v) for k,v in zip(names,x)}
p['w0']=2*np.pi*60
sub={
 "params":p,
 "defs":{
   "a":"P0*XL/V0",
   "b":"Q0*XL/V0+V0",
   "E0":"sqrt(a**2+b**2)",
   "E":"E0+kpq*(Q0-Qm)+xq+kvs*(Vset-V0)",
   "ang":"dl-theta",
   "Pe":"V*E*sin(ang)/XL",
   "Qe":"V*(E*cos(ang)-V)/XL"
 },
 "states":{
   "Pm":{"rhs":"(Pe-Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Qe-Qm)/TQf","init":"Q0"},
   "dl":{"rhs":"w0*mp*(P0-Pm)","init":"theta0+atan2(a,b)"},
   "xq":{"rhs":"kiq*(Q0-Qm)","init":"0.0"}
 },
 "outputs":{"P":"Pe","Q":"Qe"}
}
json.dump(sub,open('submission.json','w'),indent=1)
print(json.dumps(sub,indent=1))
